import { createContext, useState } from 'react';

const FeedbackContext = createContext();

const FeedbackProvider = ({ children }) => {
  const [feedback, setFeedback] = useState({
    questions: [
      { id: 1, text: 'How would you rate the overall quality of the lesson?' },
      { id: 2, text: 'Was the lesson engaging?' },
      { id: 3, text: 'Would you recommend this lesson to a friend?' },
    ],
    responses: [],
  });

  const addResponse = (questionId, response) => {
    setFeedback((prevFeedback) => {
      return { ...prevFeedback, responses: [...prevFeedback.responses, { questionId, response }] };
    });
  };

  return (
    <FeedbackContext.Provider value={{ feedback, addResponse }}>
      {children}
    </FeedbackContext.Provider>
  );
};

export { FeedbackContext, FeedbackProvider };
```
